import React, { useState, useEffect } from "react";
import axios from "axios";

const MarketHeader = () => {
  const [nifty, setNifty] = useState(0);
  const [sensex, setSensex] = useState(0);

  const fetchRealData = async () => {
    const options = {
      method: 'GET',
      url: 'https://yahoo-finance1.p.rapidapi.com/market/get-quotes',
      params: { symbols: '^BSESN,^NSEI' }, // ^BSESN = Sensex, ^NSEI = Nifty 50
      headers: {
        'X-RapidAPI-Key': '', // <--- Apni Key yahan dalo
        'X-RapidAPI-Host': 'yahoo-finance1.p.rapidapi.com'
      }
    };

    try {
      const response = await axios.request(options);
      const data = response.data.quotes;

      // Nifty 50 ka price set karein
      const niftyData = data.find(item => item.symbol === '^NSEI');
      if (niftyData) setNifty(niftyData.regularMarketPrice.toFixed(2));

      // Sensex ka price set karein
      const sensexData = data.find(item => item.symbol === '^BSESN');
      if (sensexData) setSensex(sensexData.regularMarketPrice.toFixed(2));

    } catch (error) {
      console.error("API Error:", error);
    }
  };

  useEffect(() => {
    fetchRealData(); // Pehli baar load hone par
    const interval = setInterval(fetchRealData, 10000); // Har 10 second mein asli data laega
    return () => clearInterval(interval);
  }, []);

  return (
    <div className="market-header" style={{ display: "flex", gap: "20px", padding: "10px", fontSize: "14px", fontWeight: "bold" }}>
      <div>
        <span style={{ color: "#8c8c8c" }}>NIFTY 50 </span>
        <span style={{ color: "#df514c" }}>{nifty > 0 ? nifty : "Loading..."}</span> 
      </div>
      <div>
        <span style={{ color: "#8c8c8c" }}>SENSEX </span>
        <span style={{ color: "#df514c" }}>{sensex > 0 ? sensex : "Loading..."}</span>
      </div>
    </div>
  );
};

export default MarketHeader;
